#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace Xiaoduan.Panopticon {
 public static class Room2VisualPolish {
 public static string Apply(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit mode required");var h=UnityEngine.Object.FindFirstObjectByType<PanopticonHall>();var scene=h.gameObject.scene;EditorSceneManager.SaveScene(scene);string backup="Library/Room2PolishBackup/"+DateTime.Now.ToString("yyyyMMdd_HHmmss");Directory.CreateDirectory(backup);File.Copy(scene.path,backup+"/ROOM2.unity");
 var report=new List<string>();foreach(var m in h.memories)foreach(var r in m.surfaces){var tex=(Texture2D)r.sharedMaterial.GetTexture("_Hologram_Texture");string path=AssetDatabase.GetAssetPath(tex);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.GetSourceTextureWidthAndHeight(out int w,out int ht);File.Copy(path+".meta",backup+"/"+tex.name+".meta",true);importer.npotScale=TextureImporterNPOTScale.None;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();
 var filter=r.GetComponent<MeshFilter>();var old=filter.sharedMesh;var mesh=UnityEngine.Object.Instantiate(old);mesh.name=old.name+" - aspect corrected";var vertices=mesh.vertices;bool portrait=r.name.Contains("clinical portrait");float sourceRatio=(float)w/ht;float xScale=portrait?old.bounds.size.y*sourceRatio/old.bounds.size.x:1;float yScale=portrait?1:old.bounds.size.x/sourceRatio/old.bounds.size.y;for(int j=0;j<vertices.Length;j++){vertices[j].x*=xScale;vertices[j].y*=yScale;}mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateBounds();string mp="Assets/Room2/Panopticon/Meshes/"+tex.name+"_AspectCorrect.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(mp);if(existing!=null){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,mp);filter.sharedMesh=mesh;EditorUtility.SetDirty(filter);report.Add(tex.name+": source "+w+"x"+ht+", mesh "+mesh.bounds.size.x.ToString("F3")+"x"+mesh.bounds.size.y.ToString("F3"));}
 var clinical=(Texture2D)UnityEngine.Object.FindFirstObjectByType<Xiaoduan.Clinical.ClinicalDesk>().clinicalImage;var paths=AssetDatabase.FindAssets("t:Texture2D",new[]{"Assets/Room2/ClinicalDesk/Resources","Assets/Room2/Handprints/Textures"}).Select(AssetDatabase.GUIDToAssetPath).Concat(new[]{AssetDatabase.GetAssetPath(clinical)}).Distinct();
 foreach(var path in paths){var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer==null)continue;importer.GetSourceTextureWidthAndHeight(out int w,out int ht);if(Mathf.IsPowerOfTwo(w)&&Mathf.IsPowerOfTwo(ht))continue;File.Copy(path+".meta",backup+"/"+Path.GetFileName(path)+".meta",true);importer.npotScale=TextureImporterNPOTScale.None;importer.SaveAndReimport();report.Add("Preserved source aspect: "+path);}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return backup+"\n"+string.Join("\n",report);
 }
 }
}
#endif
